begin;
create table if not exists public.hh_plans(id uuid primary key default gen_random_uuid(), fid uuid not null references public.hh_families on delete cascade, kind text not null check(kind in ('calendar','tasks')), title text not null check(length(trim(title)) between 1 and 200), due date, assignee uuid references auth.users on delete set null, done boolean not null default false, author uuid references auth.users on delete set null);
create table if not exists public.hh_profiles(uid uuid primary key references auth.users on delete cascade, name text not null check(length(name)<=80), avatar text not null check(length(avatar)<=16), preferences text not null check(length(preferences)<=200));
alter table public.hh_plans enable row level security;
alter table public.hh_profiles enable row level security;
revoke all on public.hh_plans,public.hh_profiles from public,anon,authenticated;
create or replace function public.hh_plans_list(f uuid) returns setof public.hh_plans language sql security definer set search_path='' as $$ select p.* from public.hh_plans p where p.fid=f and exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=auth.uid()) order by p.done,p.due nulls last,p.id $$;
create or replace function public.hh_plan_add(f uuid,k text,t text,d date,a uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=auth.uid()) or (a is not null and not exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=a)) then raise exception 'Non autorizzato'; end if; if k='calendar' and d is null then raise exception 'Data obbligatoria'; end if; insert into public.hh_plans(fid,kind,title,due,assignee,author) values(f,k,trim(t),d,a,auth.uid()); end $$;
create or replace function public.hh_plan_change(f uuid,i uuid,op text) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=auth.uid()) then raise exception 'Non autorizzato'; end if; if op='toggle' then update public.hh_plans set done=not done where fid=f and id=i; elsif op='delete' then delete from public.hh_plans where fid=f and id=i; else raise exception 'Azione non valida'; end if; end $$;
create or replace function public.hh_profile_get() returns setof public.hh_profiles language sql security definer set search_path='' as $$ select * from public.hh_profiles where uid=auth.uid() $$;
create or replace function public.hh_profile_save(n text,a text,p text) returns void language sql security definer set search_path='' as $$ insert into public.hh_profiles values(auth.uid(),n,a,p) on conflict(uid) do update set name=excluded.name,avatar=excluded.avatar,preferences=excluded.preferences $$;
revoke all on function public.hh_plans_list(uuid),public.hh_plan_add(uuid,text,text,date,uuid),public.hh_plan_change(uuid,uuid,text),public.hh_profile_get(),public.hh_profile_save(text,text,text) from public,anon;
grant execute on function public.hh_plans_list(uuid),public.hh_plan_add(uuid,text,text,date,uuid),public.hh_plan_change(uuid,uuid,text),public.hh_profile_get(),public.hh_profile_save(text,text,text) to authenticated;
commit;
